// Valida o JSON do Redator: só valores dos campos de IA (o texto da peça fica no banco).
const pc = $('Peças para gerar (marca como gerando)').item.json;
const raw = String($json.output ?? $json.text ?? '').replace(/^```(json)?/, '').replace(/```$/, '').trim();
let out = null, erro = null;
try { out = JSON.parse(raw); } catch (e) { erro = 'JSON inválido: ' + e.message; }
if (out && (typeof out.valores !== 'object' || Array.isArray(out.valores) || out.valores === null)) out.valores = {};
const usage = $json.tokenUsage ?? $json.usage ?? {};
const tokens_in = usage.promptTokens ?? usage.input_tokens ?? null, tokens_out = usage.completionTokens ?? usage.output_tokens ?? null;
const price_in = Number($env.LLM_PRICE_IN_PER_MTOK ?? 3), price_out = Number($env.LLM_PRICE_OUT_PER_MTOK ?? 15);
const cost_usd = (tokens_in != null && tokens_out != null) ? +((tokens_in * price_in + tokens_out * price_out) / 1e6).toFixed(6) : null;
return [{ json: { piece_id: pc.piece_id, ok: !!out, valores: out?.valores ?? {}, resumo_executivo: out?.resumo_executivo ?? null,
                  documentos_anexar: Array.isArray(out?.documentos_anexar) ? out.documentos_anexar : [],
                  qualidade: out?.qualidade ?? null, erro: erro ?? (out ? null : raw.slice(0, 300)),
                  ai_meta: { agent_role: 'redacao', model: 'claude-sonnet-5', tokens_in, tokens_out, cost_usd } } }];
